@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;700;900&display=swap');
@import url('https://cdn.jsdelivr.net/npm/remixicon@3.5.0/fonts/remixicon.css');

:root {
  --bg-primary: #000000;
  --bg-secondary: #141414;
  --bg-tertiary: #232323;
  --accent-red: #E50914;
  --accent-hover: #C11119;
  --text-primary: #FFFFFF;
  --text-secondary: rgba(255, 255, 255, 0.7);
  --border-color: rgba(255, 255, 255, 0.2);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: 'Inter', system-ui, -apple-system, sans-serif;
  background-color: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

a {
  color: var(--text-primary);
  text-decoration: none;
}

button {
  cursor: pointer;
  font-family: inherit;
  border: none;
}

/* Header */
.header {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 24px 5%;
  z-index: 10;
}

.logo {
  font-size: 2.2rem;
  font-weight: 900;
  color: var(--accent-red);
  letter-spacing: -1px;
}

.header-actions {
  display: flex;
  gap: 16px;
  align-items: center;
}

.lang-select {
  background: transparent;
  color: var(--text-primary);
  border: 1px solid var(--border-color);
  padding: 8px 16px;
  border-radius: 4px;
  font-size: 1rem;
  appearance: none;
  background-image: url("data:image/svg+xml;charset=US-ASCII,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22292.4%22%20height%3D%22292.4%22%3E%3Cpath%20fill%3D%22%23FFFFFF%22%20d%3D%22M287%2069.4a17.6%2017.6%200%200%200-13-5.4H18.4c-5%200-9.3%201.8-12.9%205.4A17.6%2017.6%200%200%200%200%2082.2c0%205%201.8%209.3%205.4%2012.9l128%20127.9c3.6%203.6%207.8%205.4%2012.8%205.4s9.2-1.8%2012.8-5.4L287%2095c3.5-3.5%205.4-7.8%205.4-12.8%200-5-1.9-9.2-5.5-12.8z%22%2F%3E%3C%2Fsvg%3E");
  background-repeat: no-repeat;
  background-position: right 12px top 50%;
  background-size: 12px auto;
  padding-right: 32px;
}

.lang-select option {
  background: var(--bg-tertiary);
  color: var(--text-primary);
}

.btn-primary {
  background-color: var(--accent-red);
  color: var(--text-primary);
  padding: 8px 16px;
  border-radius: 4px;
  font-weight: 500;
  font-size: 1rem;
  transition: background-color 0.2s;
  text-decoration: none;
  display: inline-block;
}

.btn-primary:hover {
  background-color: var(--accent-hover);
}

.btn-large {
  padding: 16px 24px;
  font-size: 1.2rem;
  font-weight: 700;
  display: flex;
  align-items: center;
  gap: 8px;
}

/* Hero Section */
.hero {
  position: relative;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 120px 5% 60px;
  background: linear-gradient(to top, rgba(0, 0, 0, 0.9) 0, rgba(0, 0, 0, 0.4) 60%, rgba(0, 0, 0, 0.9) 100%),
              url('https://images.unsplash.com/photo-1574267432553-4b4628081c31?auto=format&fit=crop&w=2000&q=80') center/cover;
}

.hero-content {
  max-width: 900px;
  z-index: 2;
}

.hero h1 {
  font-size: 4rem;
  font-weight: 900;
  margin-bottom: 16px;
  line-height: 1.1;
}

.hero .subtitle {
  font-size: 1.5rem;
  font-weight: 500;
  margin-bottom: 24px;
}

.hero .prompt {
  font-size: 1.1rem;
  margin-bottom: 16px;
}

.email-form {
  display: flex;
  flex-direction: column;
  gap: 16px;
  max-width: 600px;
  margin: 0 auto;
}

.email-input {
  flex: 1;
  padding: 16px;
  background: rgba(22, 22, 22, 0.7);
  border: 1px solid var(--border-color);
  border-radius: 4px;
  color: var(--text-primary);
  font-size: 1rem;
}

.email-input:focus {
  outline: 2px solid white;
  background: rgba(0, 0, 0, 0.8);
}

@media (min-width: 768px) {
  .email-form {
    flex-direction: row;
    gap: 8px;
  }
}

/* Sections Base */
.section {
  padding: 80px 5%;
  border-top: 8px solid var(--bg-tertiary);
}

.section-title {
  font-size: 2.5rem;
  font-weight: 700;
  margin-bottom: 32px;
}

/* Trending Carousel */
.trending {
  position: relative;
}

.carousel-container {
  display: flex;
  overflow-x: auto;
  gap: 24px;
  padding: 20px 0;
  scroll-behavior: smooth;
  -ms-overflow-style: none;
  scrollbar-width: none;
}

.carousel-container::-webkit-scrollbar {
  display: none;
}

.trending-card {
  flex: 0 0 200px;
  position: relative;
  transition: transform 0.2s;
  cursor: pointer;
}

.trending-card:hover {
  transform: scale(1.05);
}

.trending-card img {
  width: 100%;
  aspect-ratio: 2/3;
  object-fit: cover;
  border-radius: 8px;
}

.rank-number {
  position: absolute;
  bottom: -20px;
  left: -10px;
  font-size: 8rem;
  font-weight: 900;
  color: black;
  -webkit-text-stroke: 4px var(--text-secondary);
  line-height: 1;
  z-index: -1; /* Place behind image but still visible mostly */
}

/* Actually place number partly behind or over. Netflix puts it beside. Let's place it over slightly. */
.trending-card-inner {
  display: flex;
  align-items: center;
  position: relative;
}
.rank-number {
  position: absolute;
  bottom: 0px;
  left: -20px;
  font-size: 6rem;
  font-weight: 900;
  color: var(--bg-primary);
  -webkit-text-stroke: 2px var(--text-secondary);
  z-index: 1;
}
.trending-card img {
  margin-left: 30px;
  width: calc(100% - 30px);
}

.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  background: rgba(0, 0, 0, 0.5);
  color: white;
  width: 48px;
  height: 48px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  z-index: 5;
}

.carousel-btn:hover {
  background: rgba(0, 0, 0, 0.8);
}

.btn-left { left: 1%; }
.btn-right { right: 1%; }

/* Features Grid */
.features-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 24px;
}

@media (min-width: 768px) {
  .features-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .features-grid {
    grid-template-columns: repeat(4, 1fr);
  }
}

.feature-card {
  background: linear-gradient(135deg, var(--bg-tertiary) 0%, #1a1a1a 100%);
  border-radius: 16px;
  padding: 24px;
  display: flex;
  flex-direction: column;
  position: relative;
  min-height: 240px;
}

.feature-card h3 {
  font-size: 1.5rem;
  margin-bottom: 12px;
}

.feature-card p {
  color: var(--text-secondary);
  font-size: 1rem;
}

.feature-icon {
  position: absolute;
  bottom: 24px;
  right: 24px;
  font-size: 3rem;
  color: var(--accent-red);
}

/* FAQ Accordion */
.faq-list {
  max-width: 800px;
  margin: 0 auto;
}

.faq-item {
  margin-bottom: 8px;
}

.faq-question {
  background: var(--bg-tertiary);
  width: 100%;
  text-align: left;
  padding: 24px;
  font-size: 1.5rem;
  font-weight: 500;
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: var(--text-primary);
  transition: background-color 0.2s;
}

.faq-question:hover {
  background: #333;
}

.faq-answer {
  background: var(--bg-tertiary);
  padding: 0 24px;
  font-size: 1.2rem;
  line-height: 1.6;
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease, padding 0.3s ease;
  margin-top: 2px;
}

.faq-item.active .faq-answer {
  padding: 24px;
  max-height: 500px;
}

.faq-item.active .faq-icon {
  transform: rotate(45deg);
}

.faq-icon {
  transition: transform 0.3s ease;
}

/* Bottom CTA */
.cta-section {
  text-align: center;
  padding: 80px 5%;
}

.cta-section .prompt {
  font-size: 1.2rem;
  margin-bottom: 24px;
}

/* Footer */
.footer {
  padding: 80px 5%;
  color: var(--text-secondary);
  max-width: 1000px;
  margin: 0 auto;
}

.footer-contact {
  margin-bottom: 32px;
}

.footer-contact a {
  color: var(--text-secondary);
  text-decoration: underline;
}

.footer-links {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
  margin-bottom: 32px;
}

@media (min-width: 768px) {
  .footer-links {
    grid-template-columns: repeat(4, 1fr);
  }
}

.footer-links a {
  color: var(--text-secondary);
  font-size: 0.9rem;
  text-decoration: underline;
}

.footer-bottom {
  margin-top: 32px;
  font-size: 0.8rem;
}

/* Login Page Specifics */
.login-body {
  background: linear-gradient(to top, rgba(0, 0, 0, 0.5) 0, rgba(0, 0, 0, 0.5) 100%),
              url('https://images.unsplash.com/photo-1574267432553-4b4628081c31?auto=format&fit=crop&w=2000&q=80') center/cover;
}

.login-header {
  position: absolute;
  top: 0;
  left: 0;
  padding: 24px 5%;
}

.login-container {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 80px 5%;
}

.login-box {
  background: rgba(0, 0, 0, 0.75);
  padding: 48px 68px;
  border-radius: 4px;
  width: 100%;
  max-width: 450px;
  margin-top: 40px;
}

.login-box h1 {
  font-size: 2rem;
  margin-bottom: 28px;
}

.login-form {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.login-input {
  background: #333;
  border: 1px solid transparent;
  padding: 16px;
  border-radius: 4px;
  color: white;
  font-size: 1rem;
}

.login-input:focus {
  outline: none;
  background: #444;
  border-color: #fff;
}

.login-btn {
  background: var(--accent-red);
  color: white;
  padding: 16px;
  border-radius: 4px;
  font-size: 1rem;
  font-weight: 500;
  margin-top: 24px;
  margin-bottom: 12px;
}

.login-btn:hover {
  background: var(--accent-hover);
}

.login-subtext {
  color: var(--text-secondary);
  text-align: center;
  margin-bottom: 16px;
  font-size: 0.9rem;
}

.login-help-toggle {
  background: transparent;
  color: var(--text-secondary);
  font-size: 0.9rem;
  margin-top: 16px;
  text-align: left;
}

.login-help-toggle:hover {
  text-decoration: underline;
}

.login-help-content {
  display: none;
  margin-top: 16px;
  font-size: 0.9rem;
  color: var(--text-secondary);
}

.login-help-content.active {
  display: block;
}

.login-footer {
  background: rgba(0, 0, 0, 0.75);
  padding: 32px 5%;
  border-top: 1px solid #333;
  margin-top: auto;
}

@media (max-width: 768px) {
  .hero h1 { font-size: 2.5rem; }
  .section-title { font-size: 2rem; }
  .login-box { padding: 32px 24px; background: black; margin-top: 80px; }
  .login-body { background: black; }
  .login-footer { background: black; border-top: none; }
}

document.addEventListener('DOMContentLoaded', () => {
  // FAQ Accordion
  const faqItems = document.querySelectorAll('.faq-item');
  faqItems.forEach(item => {
    const question = item.querySelector('.faq-question');
    question.addEventListener('click', () => {
      const isActive = item.classList.contains('active');

      // Close all open items
      faqItems.forEach(faq => {
        faq.classList.remove('active');
      });

      // If it wasn't active before, open it
      if (!isActive) {
        item.classList.add('active');
      }
    });
  });

  // Trending Carousel
  const carouselContainer = document.querySelector('.carousel-container');
  const btnLeft = document.querySelector('.btn-left');
  const btnRight = document.querySelector('.btn-right');

  if (carouselContainer && btnLeft && btnRight) {
    btnRight.addEventListener('click', () => {
      carouselContainer.scrollBy({ left: 300, behavior: 'smooth' });
    });

    btnLeft.addEventListener('click', () => {
      carouselContainer.scrollBy({ left: -300, behavior: 'smooth' });
    });
  }

  // Login Get Help Toggle
  const helpToggle = document.querySelector('.login-help-toggle');
  const helpContent = document.querySelector('.login-help-content');
  if (helpToggle && helpContent) {
    helpToggle.addEventListener('click', () => {
      helpContent.classList.toggle('active');
    });
  }
});

